// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseTokenArg,
        address nftArg,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        vm.assume(baseTokenArg != nftArg);
        vm.assume(feeRate <= 5_000);
        vm.assume(vNft > vBase ? true : true); // no-op, keep domain wide

        c.initialize(
            baseTokenArg,
            nftArg,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoy
        );

        // General rule: baseToken always equals the supplied _baseToken argument,
        // and equals it rather than the NFT address. The mutant stores the NFT
        // address in baseToken, breaking this whenever baseTokenArg != nftArg.
        assertTrue(c.baseToken() == baseTokenArg && c.baseToken() != c.nft());
    }
}

